startConsoleInterception() {
  if (this.isIntercepting) {
    return
  }
  this.isIntercepting = true

  // prevent the annoying warning box at the bottom of the screen from getting in the way:
  const IGNORED_LOGS = [
    /Failed to open debugger. Please check that the dev server is running and reload the app./,
    /Require cycle:/,
    /is missing the required default export./,
    /Attempted to import the module/,
    /The action 'RESET' with payload/,
    /The action 'POP_TO_TOP' was not handled/,
    /socket-0 binding/,
    /socket-0 bound to/,
    /Error while flushing PostHog/,
  ]

  LogBox.ignoreLogs(IGNORED_LOGS)

  configureReanimatedLogger({
    level: ReanimatedLogLevel.warn,
    strict: false, // Reanimated runs in strict mode by default
  })

  const originalConsole = {
    log: console.log,
    info: console.info,
    warn: console.warn,
    error: console.error,
    debug: console.debug,
  }

  const appendToBuffer = this.append.bind(this)

  const stringifyArg = (a: unknown): string => {
    if (a === null) return "null"
    if (a === undefined) return "undefined"
    if (typeof a === "object") {
      try {
        return JSON.stringify(a)
      } catch {
        return String(a)
      }
    }
    return String(a)
  }

  // Single interceptor that does both jobs (filter + ring-buffer) so error stacks show
  // the real call site instead of always landing on this file's wrapper line.
  const createInterceptor =
    (level: "debug" | "info" | "warn" | "error", originalFn: (...args: unknown[]) => void) =>
    (...args: unknown[]) => {
      const output = args.map(stringifyArg).join(" ")

      // Skip ignored patterns entirely in dev (no console output, no buffer entry).
      if (__DEV__ && IGNORED_LOGS.some((re) => re.test(output))) {
        return
      }

      originalFn.apply(console, args)

      appendToBuffer({
        level,
        message: output,
        source: "console",
      })
    }

  console.log = createInterceptor("info", originalConsole.log)
  console.info = createInterceptor("info", originalConsole.info)
  console.warn = createInterceptor("warn", originalConsole.warn)
  console.error = createInterceptor("error", originalConsole.error)
  console.debug = createInterceptor("debug", originalConsole.debug)
}

